    if not grid or not grid[0]:
        return grid

    bg = grid[0][0]
    rows = len(grid)
    cols = len(grid[0])

    output = [[bg] * cols for _ in range(rows)]

    for col in range(cols):
        # Find first zero position in this column
        first_zero_idx = -1
        for row in range(rows):
            if grid[row][col] == 0:
                first_zero_idx = row
                break

        if first_zero_idx != -1:
            # Column has 0s: fill from first 0 to end with 0
            for r in range(first_zero_idx, rows):
                output[r][col] = 0
        else:
            # No zeros, find first non-bg value and fill from there
            for row in range(rows):
                val = grid[row][col]
                if val != bg:
                    for r in range(row, rows):
                        output[r][col] = val
                    break

    return output
